				runGit(t, repoDir, "remote", "add", "origin", tt.originURL)
			}
			if tt.pushURL != "" {
				runGit(t, repoDir, "remote", "add", tt.pushRemote, tt.pushURL)
			}
			writeSettings(t, repoDir, tt.settingsJSON)
			t.Chdir(repoDir)
